public class Main {
    static boolean isArmstrong(int n) {
        int digits = String.valueOf(n).length();
        int sum = 0;
        int rest = n;
        while (rest > 0) {
            int d = rest % 10;
            int power = 1;
            for (int i = 0; i < digits; i++) {
                power *= d;
            }
            sum += power;
            rest /= 10;
        }
        return sum == n;
    }

    public static void main(String[] args) {
        int[] tests = {153, 9474, 9475};
        for (int t : tests) {
            System.out.println(t + " -> " + isArmstrong(t));
        }
    }
}
